/**
 * Tests for GEDCOM Multimedia Object Record Parser
 */

import { describe, it, expect, beforeEach } from "bun:test";
import { GedcomParser } from "./parser";
import { ObjectParser } from "./object-parser";
import { fixtures } from "./__tests__/fixtures";

describe("ObjectParser", () => {
  let objectParser: ObjectParser;
  let gedcomParser: GedcomParser;

  beforeEach(() => {
    objectParser = new ObjectParser();
    gedcomParser = new GedcomParser();
  });

  describe("parseObjectRecord", () => {
    it("should parse a complete object record with all fields", () => {
      const gedcomContent = fixtures.withMultimedia();
      const gedcomFile = gedcomParser.parse(gedcomContent);

      // Find first object record
      const objectRecord = gedcomFile.objects.find(
        (r) => r.id === "O1"
      );

      expect(objectRecord).toBeDefined();
      if (!objectRecord) return;

      const parsed = objectParser.parseObjectRecord(objectRecord);

      expect(parsed.id).toBe("O1");
      expect(parsed.filePath).toBe("photos/robert_young.jpg");
      expect(parsed.format).toBe("JPEG");
      expect(parsed.title).toBe("Young Robert Portrait");
      expect(parsed.description).toBeDefined();
    });

    it("should parse object record with relative file path", () => {
      const gedcomContent = fixtures.withMultimedia();
      const gedcomFile = gedcomParser.parse(gedcomContent);

      const objectRecord = gedcomFile.objects.find(
        (r) => r.id === "O1"
      );

      expect(objectRecord).toBeDefined();
      if (!objectRecord) return;

      const parsed = objectParser.parseObjectRecord(objectRecord);

      expect(parsed.filePath).toBe("photos/robert_young.jpg");
      expect(parsed.filePath.startsWith("/")).toBe(false);
    });

    it("should parse minimal object record with only file and format", () => {
      const gedcomContent = `0 HEAD
1 SOUR vamsa
1 GEDC
2 VERS 5.5.1
1 CHAR UTF-8
0 @O1@ OBJE
1 FILE document.pdf
1 FORM PDF
0 TRLR`;

      const gedcomFile = gedcomParser.parse(gedcomContent);
      const objectRecord = gedcomFile.objects.find(
        (r) => r.id === "O1"
      );

      expect(objectRecord).toBeDefined();
      if (!objectRecord) return;

      const parsed = objectParser.parseObjectRecord(objectRecord);

      expect(parsed.id).toBe("O1");
      expect(parsed.filePath).toBe("document.pdf");
      expect(parsed.format).toBe("PDF");
      expect(parsed.title).toBeUndefined();
      expect(parsed.description).toBeUndefined();
    });

    it("should handle various media formats", () => {
      const formats = ["JPEG", "PNG", "PDF", "GIF", "TIFF"];

      for (const format of formats) {
        const gedcomContent = `0 HEAD
1 SOUR vamsa
1 GEDC
2 VERS 5.5.1
1 CHAR UTF-8
0 @O1@ OBJE
1 FILE test.file
1 FORM ${format}
0 TRLR`;

        const gedcomFile = gedcomParser.parse(gedcomContent);
        const objectRecord = gedcomFile.objects.find(
          (r) => r.id === "O1"
        );

        expect(objectRecord).toBeDefined();
        if (!objectRecord) return;

        const parsed = objectParser.parseObjectRecord(objectRecord);
        expect(parsed.format).toBe(format);
      }
    });
  });

  describe("extractEventObjects", () => {
    it("should extract objects linked to birth event", () => {
      const gedcomContent = fixtures.withMultimedia();
      const gedcomFile = gedcomParser.parse(gedcomContent);

      const personRecord = gedcomFile.individuals.find(
        (r) => r.id === "I1"
      );

      expect(personRecord).toBeDefined();
      if (!personRecord) return;

      const birthObjects = objectParser.extractEventObjects(
        personRecord,
        "BIRT"
      );

      expect(birthObjects.length).toBeGreaterThan(0);
      expect(birthObjects[0]).toBe("O1");
    });

    it("should extract objects linked to marriage event", () => {
      const gedcomContent = fixtures.withMultimedia();
      const gedcomFile = gedcomParser.parse(gedcomContent);

      // Get family from individual
      const families = gedcomFile.families;
      expect(families.length).toBeGreaterThan(0);

      // Families don't have OBJE in this fixture, but we can test concept
      // In real scenario, OBJE would be under FAM MARR
    });

    it("should return empty array when event has no objects", () => {
      const gedcomContent = fixtures.simplePerson();
      const gedcomFile = gedcomParser.parse(gedcomContent);

      const personRecord = gedcomFile.individuals[0];
      expect(personRecord).toBeDefined();

      const objects = objectParser.extractEventObjects(
        personRecord,
        "BIRT"
      );

      expect(Array.isArray(objects)).toBe(true);
      expect(objects.length).toBe(0);
    });

    it("should deduplicate object references", () => {
      const gedcomContent = `0 HEAD
1 SOUR vamsa
1 GEDC
2 VERS 5.5.1
1 CHAR UTF-8
0 @I1@ INDI
1 NAME Test /Person/
1 BIRT
2 DATE 15 JAN 1950
3 OBJE @O1@
3 OBJE @O1@
0 @O1@ OBJE
1 FILE test.jpg
1 FORM JPEG
0 TRLR`;

      const gedcomFile = gedcomParser.parse(gedcomContent);
      const personRecord = gedcomFile.individuals[0];

      const objects = objectParser.extractEventObjects(
        personRecord,
        "BIRT"
      );

      // Should only have one O1, not two
      expect(objects.length).toBe(1);
      expect(objects[0]).toBe("O1");
    });
  });

  describe("validateObject", () => {
    it("should accept valid relative path", () => {
      const object = {
        id: "O1",
        filePath: "photos/image.jpg",
        format: "JPEG",
      };

      const validation = objectParser.validateObject(object);

      expect(validation.isValid).toBe(true);
      expect(validation.errors.length).toBe(0);
      expect(validation.warnings.length).toBe(0);
    });

    it("should warn on absolute Unix path", () => {
      const object = {
        id: "O1",
        filePath: "/absolute/path/to/image.jpg",
        format: "JPEG",
      };

      const validation = objectParser.validateObject(object);

      expect(validation.isValid).toBe(true);
      expect(validation.warnings.length).toBeGreaterThan(0);
      expect(validation.warnings[0]).toContain("Absolute path");
    });

    it("should warn on absolute Windows path", () => {
      const object = {
        id: "O1",
        filePath: "C:\\Users\\Pictures\\image.jpg",
        format: "JPEG",
      };

      const validation = objectParser.validateObject(object);

      expect(validation.isValid).toBe(true);
      expect(validation.warnings.length).toBeGreaterThan(0);
      expect(validation.warnings[0]).toContain("Absolute path");
    });

    it("should error on empty file path", () => {
      const object = {
        id: "O1",
        filePath: "",
        format: "JPEG",
      };

      const validation = objectParser.validateObject(object);

      expect(validation.isValid).toBe(false);
      expect(validation.errors.length).toBeGreaterThan(0);
    });

    it("should warn on non-existent file when baseDir provided", () => {
      const object = {
        id: "O1",
        filePath: "nonexistent/file.jpg",
        format: "JPEG",
      };

      const validation = objectParser.validateObject(object, "/tmp");

      // Warning should be present (file doesn't exist)
      expect(validation.warnings.length).toBeGreaterThan(0);
    });
  });

  describe("normalizeFormat", () => {
    it("should normalize common format variations", () => {
      const testCases = [
        ["jpg", "JPEG"],
        ["JPEG", "JPEG"],
        ["png", "PNG"],
        ["PNG", "PNG"],
        ["pdf", "PDF"],
        ["tiff", "TIFF"],
        ["tif", "TIFF"],
        ["bmp", "BMP"],
        ["svg", "SVG"],
        ["webp", "WEBP"],
      ];

      for (const [input, expected] of testCases) {
        const normalized = objectParser.normalizeFormat(input);
        expect(normalized).toBe(expected);
      }
    });

    it("should preserve unknown formats in uppercase", () => {
      const result = objectParser.normalizeFormat("xyz");
      expect(result).toBe("XYZ");
    });

    it("should handle lowercase and mixed case", () => {
      expect(objectParser.normalizeFormat("JpEg")).toBe("JPEG");
      expect(objectParser.normalizeFormat("pNg")).toBe("PNG");
      expect(objectParser.normalizeFormat("  PDF  ")).toBe("PDF");
    });
  });

  describe("edge cases", () => {
    it("should handle object record with no file path", () => {
      const gedcomContent = `0 HEAD
1 SOUR vamsa
1 GEDC
2 VERS 5.5.1
1 CHAR UTF-8
0 @O1@ OBJE
1 TITL Orphan Object
0 TRLR`;

      const gedcomFile = gedcomParser.parse(gedcomContent);
      const objectRecord = gedcomFile.objects.find(
        (r) => r.id === "O1"
      );

      expect(objectRecord).toBeDefined();
      if (!objectRecord) return;

      const parsed = objectParser.parseObjectRecord(objectRecord);

      expect(parsed.filePath).toBe("");
      expect(parsed.title).toBe("Orphan Object");
    });

    it("should handle object record with empty file path", () => {
      const object = {
        id: "O1",
        filePath: "   ",
        format: "JPEG",
      };

      const validation = objectParser.validateObject(object);

      expect(validation.isValid).toBe(false);
    });

    it("should handle object with nested directory paths", () => {
      const object = {
        id: "O1",
        filePath: "media/photos/2020/family/portrait.jpg",
        format: "JPEG",
      };

      const validation = objectParser.validateObject(object);

      expect(validation.isValid).toBe(true);
      expect(validation.warnings.length).toBe(0);
    });

    it("should handle multiple NOTE lines for description", () => {
      const gedcomContent = `0 HEAD
1 SOUR vamsa
1 GEDC
2 VERS 5.5.1
1 CHAR UTF-8
0 @O1@ OBJE
1 FILE test.jpg
1 FORM JPEG
1 NOTE This is a note
1 NOTE This is another note
0 TRLR`;

      const gedcomFile = gedcomParser.parse(gedcomContent);
      const objectRecord = gedcomFile.objects.find(
        (r) => r.id === "O1"
      );

      expect(objectRecord).toBeDefined();
      if (!objectRecord) return;

      const parsed = objectParser.parseObjectRecord(objectRecord);

      // Should concatenate multiple notes
      expect(parsed.description).toBeDefined();
    });
  });
});

import { describe, it, expect, beforeEach } from "bun:test";
import { GedcomParser } from "./parser";
import { GedcomMapper } from "./mapper";
import { GedcomGenerator } from "./generator";
import type {
  VamsaPerson,
  VamsaRelationship,
} from "./mapper-types";

describe("GEDCOM Roundtrip: Import → Export → Re-import", () => {
  let parser: GedcomParser;
  let mapper: GedcomMapper;
  let generator: GedcomGenerator;

  beforeEach(() => {
    parser = new GedcomParser();
    mapper = new GedcomMapper();
    generator = new GedcomGenerator();
  });

  // Helper function for import-export-reimport cycle
  function roundtripImportExport(originalGedcom: string) {
    // 1. Parse original GEDCOM
    const originalParsed = parser.parse(originalGedcom);

    // 2. Map to Vamsa
    const mapped = mapper.mapFromGedcom(originalParsed);

    // 3. Map back to GEDCOM format
    const remapped = mapper.mapToGedcom(mapped.people, mapped.relationships);

    // 4. Generate new GEDCOM
    const generated = generator.generate(
      remapped.individuals,
      remapped.families
    );

    // 5. Re-parse generated GEDCOM
    const reparsed = parser.parse(generated);

    return {
      originalParsed,
      mapped,
      remapped,
      generated,
      reparsed,
    };
  }

  it("should preserve simple single person data through roundtrip", () => {
    const singlePersonGedcom = `0 HEAD
1 SOUR TestApp
1 GEDC
2 VERS 5.5.1
1 CHAR UTF-8
0 @I1@ INDI
1 NAME John /Smith/
1 SEX M
1 BIRT
2 DATE 15 JAN 1985
2 PLAC New York, NY
1 OCCU Engineer
1 NOTE Professional bio
0 TRLR`;

    const result = roundtripImportExport(singlePersonGedcom);

    // Verify structure preserved
    expect(result.originalParsed.individuals).toHaveLength(1);
    expect(result.reparsed.individuals).toHaveLength(1);

    // Verify person data preserved
    const originalPerson = parser.parseIndividual(
      result.originalParsed.individuals[0]
    );
    const reparsedPerson = parser.parseIndividual(
      result.reparsed.individuals[0]
    );

    expect(reparsedPerson.names[0].firstName).toBe(
      originalPerson.names[0].firstName
    );
    expect(reparsedPerson.names[0].lastName).toBe(
      originalPerson.names[0].lastName
    );
    expect(reparsedPerson.sex).toBe(originalPerson.sex);
    expect(reparsedPerson.birthDate).toBe(originalPerson.birthDate);
    expect(reparsedPerson.birthPlace).toBe(originalPerson.birthPlace);
    expect(reparsedPerson.occupation).toBe(originalPerson.occupation);
    expect(reparsedPerson.notes[0]).toBe(originalPerson.notes[0]);
  });

  it("should preserve three-generation family structure through roundtrip", () => {
    const threeGenerationGedcom = `0 HEAD
1 SOUR TestApp
1 GEDC
2 VERS 5.5.1
1 CHAR UTF-8
0 @I1@ INDI
1 NAME John /Smith/
1 SEX M
1 BIRT
2 DATE 1955
1 FAMS @F1@
0 @I2@ INDI
1 NAME Mary /Doe/
1 SEX F
1 BIRT
2 DATE 1960
1 FAMS @F1@
0 @I3@ INDI
1 NAME Robert /Smith/
1 SEX M
1 BIRT
2 DATE 1985
1 FAMC @F1@
1 FAMS @F2@
0 @I4@ INDI
1 NAME Emma /Smith/
1 SEX F
1 BIRT
2 DATE 1987
1 FAMC @F1@
0 @I5@ INDI
1 NAME James /Brown/
1 SEX M
1 BIRT
2 DATE 1980
1 FAMS @F2@
0 @I6@ INDI
1 NAME Lucy /Smith/
1 SEX F
1 BIRT
2 DATE 2010
1 FAMC @F2@
0 @F1@ FAM
1 HUSB @I1@
1 WIFE @I2@
1 CHIL @I3@
1 CHIL @I4@
1 MARR
2 DATE 10 JUN 1980
2 PLAC Boston, MA
0 @F2@ FAM
1 HUSB @I5@
1 WIFE @I3@
1 CHIL @I6@
1 MARR
2 DATE 15 AUG 2008
0 TRLR`;

    const result = roundtripImportExport(threeGenerationGedcom);

    // Verify structure preserved
    expect(result.originalParsed.individuals).toHaveLength(6);
    expect(result.originalParsed.families).toHaveLength(2);
    expect(result.reparsed.individuals).toHaveLength(6);
    expect(result.reparsed.families).toHaveLength(2);

    // Verify relationships preserved
    const originalFamily1 = parser.parseFamily(
      result.originalParsed.families[0]
    );
    const reparsedFamily1 = parser.parseFamily(result.reparsed.families[0]);

    expect(reparsedFamily1.children).toHaveLength(
      originalFamily1.children.length
    );
    expect(reparsedFamily1.children).toEqual(
      expect.arrayContaining([expect.any(String)])
    );

    // Verify Robert is in both families
    const mapped = result.mapped;
    const robertRelationships = mapped.relationships.filter((r) =>
      [r.personId, r.relatedPersonId].includes(
        mapped.people.find((p) => p.firstName === "Robert")?.id || ""
      )
    );
    expect(robertRelationships.length).toBeGreaterThan(0);
  });

  it("should preserve multiple marriages with children through roundtrip", () => {
    const multipleMarriagesGedcom = `0 HEAD
1 SOUR TestApp
1 GEDC
2 VERS 5.5.1
1 CHAR UTF-8
0 @I1@ INDI
1 NAME George /Person/
1 SEX M
1 FAMS @F1@
1 FAMS @F2@
0 @I2@ INDI
1 NAME Alice /First/
1 SEX F
1 FAMS @F1@
0 @I3@ INDI
1 NAME Bob /Child1/
1 SEX M
1 FAMC @F1@
0 @I4@ INDI
1 NAME Charlie /Child1/
1 SEX M
1 FAMC @F1@
0 @I5@ INDI
1 NAME Diana /Second/
1 SEX F
1 FAMS @F2@
0 @I6@ INDI
1 NAME Eve /Child2/
1 SEX F
1 FAMC @F2@
0 @I7@ INDI
1 NAME Frank /Child2/
1 SEX M
1 FAMC @F2@
0 @F1@ FAM
1 HUSB @I1@
1 WIFE @I2@
1 CHIL @I3@
1 CHIL @I4@
1 MARR
2 DATE 1990
0 @F2@ FAM
1 HUSB @I1@
1 WIFE @I5@
1 CHIL @I6@
1 CHIL @I7@
1 MARR
2 DATE 2000
0 TRLR`;

    const result = roundtripImportExport(multipleMarriagesGedcom);

    // Verify families preserved
    expect(result.originalParsed.families).toHaveLength(2);
    expect(result.reparsed.families).toHaveLength(2);

    // Verify all individuals preserved
    expect(result.originalParsed.individuals).toHaveLength(7);
    expect(result.reparsed.individuals).toHaveLength(7);

    // Verify George is in both families (original)
    const originalFamily1 = parser.parseFamily(
      result.originalParsed.families[0]
    );
    const originalFamily2 = parser.parseFamily(
      result.originalParsed.families[1]
    );
    expect(originalFamily1.husband).toBe(originalFamily2.husband);

    // Verify children are not confused between families (original)
    expect(originalFamily1.children).toContain("I3");
    expect(originalFamily1.children).toContain("I4");
    expect(originalFamily2.children).toContain("I6");
    expect(originalFamily2.children).toContain("I7");

    // Verify reparsed structure (after roundtrip)
    const reparsedFamily1 = parser.parseFamily(result.reparsed.families[0]);
    const reparsedFamily2 = parser.parseFamily(result.reparsed.families[1]);

    // Both families should exist with correct spouse pairs
    expect(reparsedFamily1.husband).toBeDefined();
    expect(reparsedFamily1.wife).toBeDefined();
    expect(reparsedFamily2.husband).toBeDefined();
